def rgb_to_hsv(r, g, b):
    mx = max(r, g, b)
    mn = min(r, g, b)
    v = mx
    delta = mx - mn
    s = 0.0 if v == 0 else delta / v
    if delta == 0:
        h = 0.0
    elif mx == r:
        h = ((g - b) / delta) % 6
    elif mx == g:
        h = (b - r) / delta + 2
    else:
        h = (r - g) / delta + 4
    h /= 6.0
    if h < 0:
        h += 1.0
    return (h, s, v)
